<template>
  <router-view></router-view>
</template>

<script setup>
import { useRouter } from 'vue-router';

const router = useRouter();

// Check if the user is logged in, if not, redirect to the login page
if (!localStorage.getItem('isLoggedIn')) {
  router.push('/login');
}
</script>

