<template>
  <div style="display: flex;">
    <!-- 菜单部分 -->
    <div style="width: 200px;"> <!-- 设置菜单宽度 -->
      <el-menu :default-active="activeMenu" mode="vertical" @select="navigateTo"> <!-- 绑定 select 事件到 navigateTo 函数 -->
        <!-- 动态渲染菜单项 -->
        <el-menu-item v-for="menu in menuList" :key="menu.index" :index="menu.index">
          <template #title>
            <!-- 修改此处，动态加载图标 -->
            <el-icon v-if="menu.icon">
              <component :is="resolveIcon(menu.icon)" />
            </el-icon>
            {{ menu.title }}
          </template>
        </el-menu-item>
      </el-menu>
    </div>
    <!-- 内容部分 -->
    <div class="content">
      <!-- 这里可以添加具体的内容 -->
      <router-view></router-view>
    </div>
  </div>
</template>

<script setup>
import { ref, onMounted } from 'vue';
import { useRouter } from 'vue-router';
// 引入图标库
import * as ElementPlusIconsVue from '@element-plus/icons-vue';

const activeMenu = ref('');
const router = useRouter();
const menuList = ref([]);

// 解析图标函数
const resolveIcon = (iconName) => {
  return ElementPlusIconsVue[iconName];
};

const navigateTo = (path) => {
  // 移除多余的 home 路径
  const cleanPath = '/home' + path.replace(/^home/, ''); 
  router.push(cleanPath);
  console.log(path);
  activeMenu.value = path;
};

onMounted(async () => {
  try {
    // const response = await axios.get('your-api-url'); // 替换为实际的后端 API 地址
    menuList.value = [
      {
        "index": "home/user-management",
        "icon": "User",
        "title": "用户管理"
      },
      {
        "index": "home/role-management",
        "icon": "Avatar",
        "title": "角色管理"
      },
      {
        "index": "home/permission-management",
        "icon": "Lock",
        "title": "权限管理"
      },
      {
        "index": "home/excel-management",
        "icon": "Film",
        "title": "表格管理"
      },
      {
        "index": "home/json-management",
        "icon": "Film",
        "title": "Json格式化"
      }
    ]
    // 设置默认激活菜单
    if (menuList.value.length > 0) {
      activeMenu.value = menuList.value[0].index;
    }
  } catch (error) {
    console.error('获取菜单数据失败:', error);
  }
});
</script>

<style scoped>
.el-icon {
  font-size: 16px; /* 设置图标大小 */
}
.content {
  padding: 20px;
  flex: 1; /* 让内容部分占据剩余空间 */
}
</style>